def enumerate_all_extensions():
    """Generate all valid topological sorts"""
    results = []

    def extend(mask, current_order):
        if mask == (1 << n) - 1:
            results.append(current_order[:])
            return

        for i in range(n):
            if not (mask & (1 << i)):
                c = int_to_coord[i]
                pred_mask = 0
                for p in predecessors[c]:
                    pred_mask |= (1 << coord_to_int[p])

                if pred_mask & mask == pred_mask:
                    current_order.append(c)
                    extend(mask | (1 << i), current_order)
                    current_order.pop()

    extend(0, [])
    return results

