from itertools import product

def count_valid():
    """Count valid T by enumerating non-increasing sequences satisfying pairing"""

    def is_valid(h):
        # h must be non-increasing (down-set)
        if not all(h[i] >= h[i+1] for i in range(9)):
            return False

        # Must use h_{9-x} = 8 - h_x for pairing symmetry
        # (This ensures |T| = 50 since sum(h[x]+1) over x = 50)
        if not all(h[x] + h[9-x] == 8 for x in range(10)):
            return False

        # Check divisibility down-set property explicitly
        # If (x,y) in T then all (x',y') with x'<x and y'<y must be in T
        for x in range(10):
            for y in range(10):
                if y <= h[x]:  # (x,y) in T
                    for xp in range(10):
                        for yp in range(10):
                            if xp <= x and yp <= y:
                                if yp > h[xp]:
                                    return False  # Violation of down-set

        return True

    count = 0
    # h[0..3] determine rest via symmetry: h[i] determines h[9-i] = 8 - h[i]
    # Need to enumerate h[0], h[1], h[2], h[3], h[4]
    # Constraint: h[0] >= h[1] >= h[2] >= h[3] >= h[4]
    # Also h[4] >= h[5] = 8 - h[4] => h[4] >= 4

    for h4 in range(4, 10):  # h[4] from 4 to 9
        for h3 in range(h4, 10):
            for h2 in range(h3, 10):
                for h1 in range(h2, 10):
                    for h0 in range(h1, 10):
                        # Now reconstruct full sequence
                        seq = [h0, h1, h2, h3, h4, 8-h4, 8-h3, 8-h2, 8-h1, 8-h0]

                        if is_valid(seq):
                            count += 1

    return count

result = count_valid()
print(f"Valid configurations: {result}")
